def solve():
    def get_p1(S):
        p1 = set()
        for f in S:
            for g in S:
                p1.add(f - g)
        return p1

    def get_p2(p1, r):
        p2 = set()
        for p in p1:
            for q in p1:
                p2.add(3 * p * q * r)
        return p2

    def get_p3(p1):
        p3 = set()
        # Optimization: x^2 + y^2 - z^2 - w^2
        # Precompute squares
        sq = {x*x for x in p1}
        for x2 in sq:
            for y2 in sq:
                for z2 in sq:
                    for w2 in sq:
                        p3.add(x2 + y2 - z2 - w2)
        return p3

    def check(r, S):
        p1 = get_p1(S)
        p2 = get_p2(p1, r)
        p3 = get_p3(p1)
        return p2.issubset(p3)

    # Test a few sets S
    test_sets = [
        {0, 1, 2},
        {0, 1, 3},
        {0, 1, 10},
        {1, 2, 4},
        {1, 2, 5},
        {0, 1, 2, 3},
        {0, 1, 2, 4},
    ]

    candidates = [0, 1/3, -1/3, 2/3, -2/3]
    for r in candidates:
        all_pass = True
        for S in test_sets:
            if not check(r, S):
