import random

def check(r, S):
    p1 = set()
    for f in S:
        for g in S:
            p1.add(f - g)

    # P2 = {3 * p * q * r for p, q in p1}
    # We need to check if 3*p*q*r is in P3 for all p, q in p1.

    sq = {x*x for x in p1}
    q_set = set()
    for x2 in sq:
        for y2 in sq:
            q_set.add(x2 + y2)

    # P3 = {q1 - q2 for q1, q2 in q_set}
    # Instead of building P3, we can check if 3*p*q*r + q2 = q1 for some q1, q2 in q_set.

    for p in p1:
        for q in p1:
            val = 3 * p * q * r
            # Check if val = q1 - q2 for some q1, q2 in q_set
            # q1 = val + q2
            found = False
            for q2 in q_set:
                if (val + q2) in q_set:
                    found = True
                    break
            if not found:
                return False
    return True

